-- Batch update order_items to avoid holding locks for too long
-- Process in chunks to allow concurrent writes between batches
DO $$
DECLARE
  batch_size INT := 2000;
  min_id INT;
  max_id INT;
  current_id INT;
BEGIN
  -- Get ID range
  SELECT COALESCE(MIN(id), 0), COALESCE(MAX(id), 0)
  INTO min_id, max_id
  FROM order_items;

  current_id := min_id;

  -- Process in batches
  WHILE current_id <= max_id LOOP
    UPDATE order_items
    SET quantity = 1
    WHERE id >= current_id 
      AND id < current_id + batch_size;

    current_id := current_id + batch_size;

    -- Small pause between batches to reduce contention
    IF current_id <= max_id THEN
      PERFORM pg_sleep(0.05);
    END IF;
  END LOOP;
END $$;",
